import glob,numpy as np,json,math
records=sorted(glob.glob('results/token_records/*.npz'))
for i in range(0,len(records),2):
 ds=[np.load(f) for f in records[i:i+2]]
 vals=[]
 for d in ds:
  logp=d['logps']; old=d['old_logps']; adv=d['advantages']; m=d['mask']; den=float(d['generation_token_count']);
  ratio=np.exp(np.clip(logp-old,-100,100)); c=np.clip(ratio,1-float(d['clip_low']),1+float(d['clip_high']));
  # adv shape B -> B,T
  p1=ratio*adv[:,None]; p2=c*adv[:,None]; pl=-np.minimum(p1,p2)
  vals.append(float((pl*m).sum()/max(den,1)))
 step=int(records[i].split('step')[1][:4]); print(step,'micro',vals,'sum',sum(vals),'loss each saved',[float(x['loss']) for x in ds])
PY",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:30000});
text(r.output);

